```js
// Resolves a ball↔brick overlap: bounces the ball off the face it most
// deeply(?) penetrated and pushes it back out of the brick rectangle so it
// cannot re-collide on the next frame (avoids the sticky double-bounce) and
// cannot re-flip across overlapping neighbour bricks.
export function bounceOffBrick(ball, brick) {
  // penetration depths from each face
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);

  // horizontal vs vertical penetration: the smaller axis is the one the ball
  // actually hit against; equal penetration means a corner (diagonal) hit.
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  if (penX < penY) {
    // side hit
    if (penLeft < penRight) {
      ball.x = brick.x - ball.r;   // push to the left
      ball.vx = Math.abs(ball.vx); // bounce rightward
    } else {
      ball.x = brick.x + brick.w + ball.r; // push to the right
      ball.vx = -Math.abs(ball.vx);        // bounce leftward
    }
  } else if (penY < penX) {
    // top/bottom hit
    if (penTop < penBottom) {
      ball.y = brick.y - ball.r;   // push above
      ball.vy = Math.abs(ball.vy); // bounce downward
    } else {
      ball.y = brick.y + brick.h + ball.r; // push below
      ball.vy = -Math.abs(ball.vy);        // bounce upward
    }
  } else {
    // corner: equal penetration — diagonal hit, flip both
    if (penLeft < penRight) {
      ball.x = brick.x - ball.r;
      ball.vx = Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = -Math.abs(ball.vx);
    }
    if (penTop < penBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = -Math.abs(ball.vy);
    }
  }
}
```

