  const ball = {
    x: 127, // brick right edge at 120, centre just outside by the radius
    y: 67, // brick top edge at 80, centre just above by the radius
    r: 7,
    vx: 300,
    vy: -260,
  };
  const brick = { x: 40, y: 80, w: 80, h: 40 };
  assert.ok(collides(ball, brick), 'ball must just overlap the corner');
  bounceOffBrick(ball, brick);
  assert.ok(ball.vx < 0, 'corner hit flips vx');
  assert.ok(ball.vy > 0, 'corner hit flips vy');
  assert.ok(!collides(ball, brick), 'ball must be pushed out of the brick');
});

test('#1 push out: after a bounce the ball never overlaps the brick again', () => {
  const ball = { x: 80, y: 60, r: 7, vx: 30, vy: -240 };
  const brick = { x: 40, y: 80, w: 80, h: 40 };
  assert.ok(collides(ball, brick), 'trivially overlapping before first bounce');
  bounceOffBrick(ball, brick);
  assert.ok(
    !collides(ball, brick),
    'after the bounce the ball must be clear (no sticky re-bounce)',
  );
});

test('#1 neighbours: overlapping two seam bricks bounces exactly once', () => {
  // Two seam-adjacent bricks with the 8px BRICK_GAP, and a ball wide enough to
  // overlap BOTH at once. frame() processes bricks sequentially: bouncing the
  // ball out after the first clears it from the second, so vy flips once, not
  // twice (a double vy = -vy cancellation is exactly the plow-through bug).
  const ball = { x: 150, y: 60, r: 7, vx: 10, vy: -260 }; // straddling the seam
  // A spans x:[40,120]; B spans x:[128,208]; the 8px seam is the real gap.
  const brickA = { x: 40, y: 80, w: 80, h: 40 };
  const brickB = { x: 128, y: 80, w: 80, h: 40 };
  assert.ok(collides(ball, brickA), 'ball overlaps the LEFT brick');
  assert.ok(collides(ball, brickB), 'ball overlaps the RIGHT brick too (seam)');

  // Process both the way frame() does: bounce the first, which must push the
  // ball clear of the neighbour so the second collision is skipped.
  const vyBefore = ball.vy;
  const vxBefore = ball.vx;
  bounceOffBrick(ball, brickA);
  assert.ok(!collides(ball, brickA), 'left brick cleared after its bounce');
  assert.ok(!collides(ball, brickB), 'and the ball is pushed clear of the right brick too');
  assert.equal(Math.sign(ball.vy), Math.sign(vyBefore), 'bounce applied exactly once (no cancellation)');
  assert.equal(Math.sign(ball.vx), -Math.sign(vxBefore), 'side face flips vx');
});

test('#1 tunnelling: a fast ball that jumps a whole brick still bounces', () => {
  // Level 6: ballSpeed(6) = 710 px/s, a 50ms stutter => up to 35.5 px per step
  // while BRICK_H + diameter = 34 px to cross. Discrete positions skip the
  // brick entirely; only a swept segment test can catch it.
  const brick = { x: 40, y: 80, w: 80, h: 40 };
  const prev = { x: 80, y: 30 }; // entirely above the brick
  const ball = { x: 80, y: 300, r: 7, vx: 0, vy: 300 }; // far PAST the brick
  assert.ok(!collides(ball, brick), 'no discrete overlap: classic tunnelling setup');
  assert.equal(sweepBounce(prev, ball, brick), true, 'swept segment must hit the brick');
  assert.ok(ball.vy < 0, 'tunnelled ball must bounce back upward');
  assert.ok(ball.y < brick.y, 'ball placed at the entry, above the brick');
});

test('#1 tunnelling: no bounce when the path misses the brick', () => {
  const brick = { x: 40, y: 80, w: 80, h: 40 };
  const prev = { x: 400, y: 30 };
  const ball = { x: 400, y: 300, r: 7, vx: 0, vy: 300 };
  assert.equal(sweepBounce(prev, ball, brick), false, 'path does not cross this brick');
  assert.equal(ball.y, 300, 'un-hit ball does not move');
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

