export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // The segment the ball travelled this step (set by step()). For a hand-built
  // ball (no prev) we fall back to the current position: the discrete bounce
  // still works, only the tunnelling sweep is skipped.
  const prev = {
    x: state.ball.prevX ?? state.ball.x,
    y: state.ball.prevY ?? state.ball.y,
  };

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Detect the hit. Discrete overlap first; if the ball jumped the brick in
    // a single stuttered step, fall back to a swept test of the segment. The
    // bounce is resolved per-face and pushes the ball OUT of the brick, which
    // clears the ball from any seam-adjacent brick in the same pass and so
    // applies each bounce exactly once.
    if (collides(state.ball, brick)) {
      bounceOffBrick(state.ball, brick);
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    } else if (sweepBounce(prev, state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

